import React from "react";
import { Link, NavLink, useSearchParams } from "react-router-dom";

// ИСПРАВЛЕННЫЕ ПУТИ: поднимаемся на 2 уровня вверх из Layout и components в папку src/assets
import plLogo from "../../assets/leagues/premier-league.png";
import blLogo from "../../assets/leagues/bundesliga.png";
import saLogo from "../../assets/leagues/serie-a.png";
import pdLogo from "../../assets/leagues/la-liga.png";
import flLogo from "../../assets/leagues/ligue-1.png";

const leagues = [
  { code: null, name: "ALL", logo: null },
  { code: "Premier_League", name: "PL", logo: plLogo },
  { code: "La_Liga", name: "LL", logo: pdLogo },
  { code: "Serie_A", name: "SA", logo: saLogo },
  { code: "Bundesliga", name: "BL", logo: blLogo },
  { code: "Ligue_1", name: "L1", logo: flLogo },
];

function Header() {
  const [searchParams] = useSearchParams();
  const currentLeagueCode = searchParams.get("league");

  return (
    <header className="bg-gray-950 border-b border-gray-900 sticky top-0 z-50 w-full overflow-hidden">
      <div className="container mx-auto px-4">
        <div className="flex items-center justify-between h-24 gap-6">
          {/* 1. ЛОГОТИП (Старый вариант с градиентом) */}
          <Link to="/" className="flex-shrink-0">
            <span className="text-2xl md:text-3xl font-black tracking-tighter text-gradient-neuro-title">
              NeuroPredict
            </span>
          </Link>

          {/* 2. ЛИНЕЙКА ЛИГ (КВАДРАТИКИ) */}
          <nav className="flex items-center gap-2 overflow-x-auto no-scrollbar py-2">
            {leagues.map((league) => {
              const isActive =
                currentLeagueCode === league.code ||
                (!currentLeagueCode && league.code === null);

              return (
                <NavLink
                  key={league.code || "all"}
                  to={league.code ? `/?league=${league.code}` : "/"}
                  className={`
                    flex-shrink-0 w-14 h-14 md:w-16 md:h-16 rounded-xl border-2 flex flex-col items-center justify-center transition-all duration-300
                    ${
                      isActive
                        ? "bg-red-600 border-red-600 shadow-[0_0_15px_rgba(220,38,38,0.3)]"
                        : "bg-gray-900 border-gray-800 hover:border-gray-600"
                    }
                  `}
                >
                  <div className="h-8 w-8 md:h-10 md:w-10 flex items-center justify-center">
                    {league.logo ? (
                      <img
                        src={league.logo}
                        alt=""
                        className="h-full w-full object-contain p-0.5"
                      />
                    ) : (
                      <span
                        className={`text-[10px] font-black ${isActive ? "text-white" : "text-gray-500"}`}
                      >
                        ALL
                      </span>
                    )}
                  </div>
                  <span
                    className={`text-[8px] font-bold mt-1 uppercase tracking-tighter ${isActive ? "text-white" : "text-gray-600"}`}
                  >
                    {league.name}
                  </span>
                </NavLink>
              );
            })}
          </nav>

          {/* 3. ФУНКЦИОНАЛЬНАЯ ЗОНА */}
          <div className="hidden lg:flex items-center gap-4">
            <div className="relative">
              <input
                type="text"
                placeholder="Поиск..."
                className="bg-gray-900 border border-gray-800 rounded-lg py-2 px-3 text-[10px] text-gray-400 w-32 focus:w-48 focus:border-red-600 transition-all outline-none"
              />
            </div>
            <button className="bg-gray-900 border border-gray-800 p-2 rounded-lg hover:border-red-600 transition-colors group">
              <span className="text-[10px] font-black text-gray-600 group-hover:text-red-600 uppercase tracking-widest">
                H2H Compare
              </span>
            </button>
          </div>
        </div>
      </div>
      <div className="h-[1px] w-full bg-gradient-to-r from-transparent via-red-600/30 to-transparent"></div>
    </header>
  );
}

export default Header;
